import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

interface SendEmailRequest {
  to: string;
  template_key: string;
  variables: Record<string, string>;
}

/** Replace {{variable}} placeholders in a template string */
function renderTemplate(template: string, variables: Record<string, string>): string {
  return template.replace(/\{\{(\w+)\}\}/g, (_, key) => variables[key] ?? "");
}

/** Map Postmark error codes to user-friendly messages */
function getPostmarkErrorMessage(errorCode: number, message: string, fromEmail: string, toEmail: string): string {
  switch (errorCode) {
    case 412:
      return `Account pending approval — emails can only be sent to @${fromEmail.split("@")[1]} addresses while your Postmark account is being reviewed. You tried sending to ${toEmail}.`;
    case 406:
      return `Inactive recipient — ${toEmail} has been marked as inactive due to previous bounces. Reactivate in Postmark dashboard.`;
    case 300:
      return `Sender signature not found — ${fromEmail} is not verified in Postmark. Add and verify this sender in your Postmark account.`;
    case 400:
      return `Bad request — ${message}`;
    case 401:
      return `Unauthorized — your Postmark API token is invalid or expired. Update it in Email Settings.`;
    case 405:
      return `Not allowed to send — ${message}`;
    case 422:
      return message || "Unprocessable request";
    default:
      return message || `Postmark error (code ${errorCode})`;
  }
}

/** Send an email via Postmark API */
async function sendViaPostmark(
  apiToken: string,
  from: { email: string; name: string },
  to: string,
  subject: string,
  htmlContent: string
): Promise<{ ok: boolean; status: number; body: string; errorCode?: number; errorMessage?: string }> {
  const res = await fetch("https://api.postmarkapp.com/email", {
    method: "POST",
    headers: {
      "Accept": "application/json",
      "Content-Type": "application/json",
      "X-Postmark-Server-Token": apiToken,
    },
    body: JSON.stringify({
      From: `${from.name} <${from.email}>`,
      To: to,
      Subject: subject,
      HtmlBody: htmlContent,
      MessageStream: "outbound",
    }),
  });

  const body = await res.text();
  let errorCode: number | undefined;
  let errorMessage: string | undefined;

  if (!res.ok) {
    try {
      const parsed = JSON.parse(body);
      errorCode = parsed.ErrorCode;
      errorMessage = parsed.Message;
    } catch { /* ignore */ }
  }

  return { ok: res.ok, status: res.status, body, errorCode, errorMessage };
}

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

  try {
    const { to, template_key, variables } = (await req.json()) as SendEmailRequest;

    if (!to || !template_key) {
      return new Response(JSON.stringify({ error: "Missing 'to' or 'template_key'" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Load platform config for Postmark credentials
    const { data: config, error: configError } = await supabase
      .from("platform_config")
      .select("postmark_api_token, email_from_address, email_from_name, outbound_email_enabled, email_notify_ranking_complete, email_notify_resume_received")
      .limit(1)
      .single();

    if (configError) throw new Error(`Config error: ${configError.message}`);

    if (!config?.outbound_email_enabled) {
      return new Response(JSON.stringify({ error: "Outbound email is disabled", skipped: true }), {
        status: 200,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    if (!config.postmark_api_token) {
      return new Response(JSON.stringify({ error: "Postmark API token not configured" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Check per-template notification settings
    if (template_key === "ranking_complete" && !config.email_notify_ranking_complete) {
      return new Response(JSON.stringify({ skipped: true, reason: "Ranking complete notifications disabled" }), {
        status: 200,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }
    if (template_key === "resume_received" && !config.email_notify_resume_received) {
      return new Response(JSON.stringify({ skipped: true, reason: "Resume received notifications disabled" }), {
        status: 200,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Load template
    const { data: template, error: tplError } = await supabase
      .from("email_templates")
      .select("subject, body_html")
      .eq("template_key", template_key)
      .single();

    if (tplError || !template) {
      return new Response(JSON.stringify({ error: `Template '${template_key}' not found` }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Render template with variables
    const subject = renderTemplate(template.subject, variables);
    const htmlContent = renderTemplate(template.body_html, variables);

    const fromEmail = config.email_from_address || "noreply@rankora.co";
    const fromName = config.email_from_name || "Rankora";

    // Send via Postmark
    const result = await sendViaPostmark(
      config.postmark_api_token,
      { email: fromEmail, name: fromName },
      to,
      subject,
      htmlContent
    );

    if (!result.ok) {
      // If Postmark account is pending approval (error 412), silently skip external domain emails
      if (result.errorCode === 412) {
        const fromDomain = fromEmail.split("@")[1];
        const toDomain = to.split("@")[1];
        if (fromDomain !== toDomain) {
          console.warn(`Postmark pending approval: skipping email to ${toDomain} (only ${fromDomain} allowed)`);
          return new Response(JSON.stringify({
            skipped: true,
            reason: `Postmark account pending approval — can only send to @${fromDomain} addresses`,
          }), {
            status: 200,
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          });
        }
      }

      const friendlyMessage = getPostmarkErrorMessage(
        result.errorCode || 0,
        result.errorMessage || "",
        fromEmail,
        to
      );

      console.error("Postmark error:", result.status, result.body);
      await logSystemError({
        function_name: "send-email",
        error_type: "POSTMARK_SEND_ERROR",
        severity: "warning",
        error_message: `Postmark error: status=${result.status} body=${result.body}`,
      });
      return new Response(JSON.stringify({
        error: friendlyMessage,
        postmark_error_code: result.errorCode,
        postmark_raw: result.errorMessage,
      }), {
        status: 502,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    return new Response(JSON.stringify({ success: true }), {
      status: 200,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (err: unknown) {
    console.error("send-email error:", err);
    await logSystemError({
      function_name: "send-email",
      error_type: "EMAIL_SEND_ERROR",
      severity: "warning",
      error_message: errorToMessage(err),
      error_stack: errorToStack(err),
    });
    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

