  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

  try {
    const { to, template_key, variables } = (await req.json()) as SendEmailRequest;

    if (!to || !template_key) {
      return new Response(JSON.stringify({ error: "Missing 'to' or 'template_key'" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Load platform config for Postmark credentials
    const { data: config, error: configError } = await supabase
      .from("platform_config")
      .select("postmark_api_token, email_from_address, email_from_name, outbound_email_enabled, email_notify_ranking_complete, email_notify_resume_received")
      .limit(1)
      .single();

    if (configError) throw new Error(`Config error: ${configError.message}`);

    if (!config?.outbound_email_enabled) {
      return new Response(JSON.stringify({ error: "Outbound email is disabled", skipped: true }), {
        status: 200,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    if (!config.postmark_api_token) {
      return new Response(JSON.stringify({ error: "Postmark API token not configured" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Check per-template notification settings
    if (template_key === "ranking_complete" && !config.email_notify_ranking_complete) {
      return new Response(JSON.stringify({ skipped: true, reason: "Ranking complete notifications disabled" }), {
        status: 200,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }
    if (template_key === "resume_received" && !config.email_notify_resume_received) {
      return new Response(JSON.stringify({ skipped: true, reason: "Resume received notifications disabled" }), {
        status: 200,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Load template
    const { data: template, error: tplError } = await supabase
      .from("email_templates")
