const ChatWidgetCard = ({ config, onConfigSaved }: { config: any; onConfigSaved: () => void }) => {
  const [open, setOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [enabled, setEnabled] = useState<boolean>(config?.chat_widget_enabled ?? false);
  const [code, setCode] = useState<string>(config?.chat_widget_code || "");

  // Sync when config loads
  useEffect(() => {
    if (config) {
      setEnabled(config.chat_widget_enabled ?? false);
      setCode(config.chat_widget_code || "");
    }
  }, [config]);

  const save = async () => {
    setSaving(true);
    try {
      const { error } = await supabase
        .from("platform_config")
        .update({
          chat_widget_enabled: enabled,
          chat_widget_code: code,
        } as any)
        .eq("id", config?.id);
      if (error) throw error;
      toast.success("Chat widget settings saved");
      logAuditAction("integration.update", "platform_config", config?.id, { integration: "chat_widget" });
      onConfigSaved();
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSaving(false);
    }
  };

  return (
    <Collapsible open={open} onOpenChange={setOpen} className="rounded-xl border bg-card shadow-sm overflow-hidden">
      <CollapsibleTrigger asChild>
        <button className="w-full flex items-center justify-between p-5 hover:bg-muted/30 transition-colors text-left">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-lg bg-orange-500/10 flex items-center justify-center shrink-0">
              <MessageCircle className="h-5 w-5 text-orange-600" />
            </div>
            <div>
              <p className="font-semibold text-sm">Chat Widget</p>
              <p className="text-xs text-muted-foreground">Embed any chat widget (Intercom, Crisp, Tawk.to, etc.)</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Badge variant={enabled ? "default" : "secondary"} className={`text-[10px] shrink-0 ${enabled ? "bg-green-600 hover:bg-green-600" : ""}`}>
              {enabled ? "Active" : "Disabled"}
            </Badge>
            <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${open ? "rotate-180" : ""}`} />
          </div>
        </button>
      </CollapsibleTrigger>

      <CollapsibleContent>
        <div className="px-5 pb-5 space-y-5">
          <Separator />

          {/* Toggle */}
          <div className="flex items-start justify-between gap-4">
            <div>
              <p className="text-sm font-medium">Enable chat widget</p>
              <p className="text-xs text-muted-foreground">When enabled, the embed code below will be injected on all pages</p>
            </div>
            <Switch checked={enabled} onCheckedChange={setEnabled} />
          </div>

          {/* Embed code */}
          <div>
            <Label className="text-xs font-medium">Embed Code</Label>
            <p className="text-xs text-muted-foreground mb-1.5">
              Paste the full embed/script code from your chat provider (e.g. Intercom, Crisp, Tawk.to, Zendesk, Drift)
            </p>
            <Textarea
              value={code}
              onChange={(e) => setCode(e.target.value)}
              placeholder={'<script src="https://your-chat-provider.com/widget.js"></script>'}
              className="font-mono text-xs min-h-[120px]"
            />
          </div>

          {/* Setup guide */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-3">Setup Guide</p>
            <div className="space-y-3 rounded-lg bg-muted/40 p-4">
              <Step n={1} text="Sign up with your preferred chat widget provider (Intercom, Crisp, Tawk.to, etc.)" />
              <Step n={2} text="Find the embed/installation code in your provider's dashboard (usually a script tag)" />
