            if (!hasAllowedExtension(att.filename)) continue;
            const fileContent = Uint8Array.from(atob(att.content), (c: string) => c.charCodeAt(0));
            // [H2 FIX] Enforce file size limit
            if (fileContent.byteLength > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
