        .from("profiles")
        .select("user_id, credits, email_enabled, inbox_email")
        .eq("inbox_email", recipient)
        .limit(1)
        .single();

      if (exactMatch) {
        profile = exactMatch;
      } else if (baseRecipient !== recipient) {
        const { data: baseMatch } = await supabase
          .from("profiles")
          .select("user_id, credits, email_enabled, inbox_email")
          .eq("inbox_email", baseRecipient)
          .limit(1)
          .single();
        profile = baseMatch;
      }

      if (!profile) {
        return await logAndRespond(404, { sender, recipient, status: "rejected", error_message: "Unknown inbox email" }, { error: "Unknown inbox email" });
      }

      userId = profile.user_id;

      // Check per-user email toggle
      if (!profile.email_enabled) {
        return await logAndRespond(403, { sender, recipient, user_id: userId, status: "rejected", error_message: "User email disabled" }, { error: "Email ingestion disabled for this user" });
      }

      // [H3 FIX] Check that user has credits before accepting resumes
      if (profile.credits <= 0) {
        return await logAndRespond(403, { sender, recipient, user_id: userId, status: "rejected", error_message: "Insufficient credits" }, { error: "Insufficient credits" });
      }
    } else {
      // Verify the job owner has email enabled and has credits
      const { data: profile } = await supabase
        .from("profiles")
        .select("email_enabled, credits")
        .eq("user_id", userId)
        .single();

      if (profile && !profile.email_enabled) {
        return await logAndRespond(403, { sender, recipient, user_id: userId, job_id: jobId, status: "rejected", error_message: "User email disabled" }, { error: "Email ingestion disabled for this user" });
      }

      // [H3 FIX] Check credits for job-routed emails too
      if (profile && profile.credits <= 0) {
        return await logAndRespond(403, { sender, recipient, user_id: userId, job_id: jobId, status: "rejected", error_message: "Insufficient credits" }, { error: "Insufficient credits" });
      }
    }

    if (attachmentFiles.length === 0) {
      return await logAndRespond(400, { sender, recipient, user_id: userId, job_id: jobId, status: "error", error_message: "No valid attachments (only .pdf and .docx accepted)" }, { error: "No valid attachments" });
    }

    // Find or create job if not already matched by per-job routing
    if (!jobId) {
      const { data: activeJob } = await supabase
        .from("jobs")
        .select("id")
        .eq("user_id", userId)
        .eq("status", "pending")
        .order("created_at", { ascending: false })
        .limit(1)
        .single();

      if (activeJob) {
        jobId = activeJob.id;
      } else {
        // [M4 FIX] Rate-limit auto-created jobs: max 5 auto-created jobs per user per day
        const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
        const { count: recentAutoJobs } = await supabase
          .from("jobs")
          .select("id", { count: "exact", head: true })
          .eq("user_id", userId)
          .eq("job_description", "Auto-created from email ingestion")
          .gte("created_at", oneDayAgo);

        if ((recentAutoJobs || 0) >= 5) {
          return await logAndRespond(429, { sender, recipient, user_id: userId, status: "rejected", error_message: "Too many auto-created jobs" }, { error: "Rate limit exceeded" });
        }

        const { data: newJob } = await supabase
          .from("jobs")
          .insert({
            user_id: userId,
            job_description: "Auto-created from email ingestion",
            status: "pending",
          })
          .select("id")
          .single();
        if (!newJob) throw new Error("Failed to create job");
        jobId = newJob.id;
      }
    }

    // [H3 FIX] Check existing resume count for the job before uploading
    const { count: existingResumeCount } = await supabase
      .from("resumes")
      .select("id", { count: "exact", head: true })
      .eq("job_id", jobId);

    const remainingSlots = maxResumesPerJob - (existingResumeCount || 0);
    if (remainingSlots <= 0) {
      return await logAndRespond(429, { sender, recipient, user_id: userId, job_id: jobId, status: "rejected", error_message: "Job has reached maximum resume limit" }, { error: "Resume limit reached for this job" });
    }

    // Process attachments (limited to remaining slots)
    const resumeIds: string[] = [];
    const filesToProcess = attachmentFiles.slice(0, remainingSlots);

    for (const att of filesToProcess) {
      // [M4 FIX] Sanitize filename to prevent path traversal or injection
      const safeName = sanitizeFilename(att.filename);
      const filePath = `${userId}/${jobId}/${Date.now()}_${safeName}`;
      await supabase.storage.from("resumes").upload(filePath, att.content);

      const { data: resume } = await supabase
        .from("resumes")
        .insert({
          job_id: jobId,
          filename: safeName,
          file_path: filePath,
          source: "email",
        })
        .select("id")
        .single();

      if (resume) resumeIds.push(resume.id);
    }

    // Send confirmation email to the user (fire-and-forget)
    try {
      const { data: authUser } = await supabase.auth.admin.getUserById(userId!);
      const userEmail = authUser?.user?.email;

      if (userEmail) {
        const { data: jobData } = await supabase.from("jobs").select("title, job_description").eq("id", jobId).single();
        const jobTitle = jobData?.title || jobData?.job_description?.slice(0, 50) || "Untitled Job";

        await supabase.functions.invoke("send-email", {
          body: {
            to: userEmail,
            template_key: "resume_received",
            variables: {
              user_name: userEmail.split("@")[0],
              job_title: jobTitle,
              attachment_count: String(filesToProcess.length),
              filename: filesToProcess.map((a) => a.filename).join(", "),
              job_id: jobId || "",
              app_url: Deno.env.get("APP_URL") || "https://rankora.co",
            },
          },
        });
      }
    } catch (emailErr) {
      console.error("Failed to send resume received notification:", emailErr);
      await logSystemError({
        function_name: "email-ingest",
        error_type: "NOTIFICATION_SEND_ERROR",
        severity: "warning",
        error_message: errorToMessage(emailErr),
        error_stack: errorToStack(emailErr),
        user_id: userId,
        job_id: jobId,
      });
    }

    return await logAndRespond(
      200,
      { sender, recipient, user_id: userId, job_id: jobId, status: "success", attachments_count: filesToProcess.length, resumes_created: resumeIds.length },
      { success: true, resume_ids: resumeIds, job_id: jobId }
    );
  } catch (err: unknown) {
    console.error("email-ingest error:", err);
    await logSystemError({
      function_name: "email-ingest",
      error_type: "INGEST_ERROR",
      severity: "critical",
      error_message: errorToMessage(err),
      error_stack: errorToStack(err),
    });
    // [H4 FIX] Return generic error — never leak internal details
    return new Response(JSON.stringify({ error: "Internal server error" }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

