312→    }
313→
314→    // Step 2: Fall back to user-level inbox routing
315→    if (!userId) {
316→      // Strip +tag for matching: abc+xyz@domain → abc@domain
317→      const baseRecipient = recipient.replace(/\+[^@]*@/, "@");
318→
319→      // [C2 FIX] Use separate parameterized .eq() queries instead of .or() with string interpolation
320→      let profile: { user_id: string; credits: number; email_enabled: boolean; inbox_email: string } | null = null;
321→
322→      const { data: exactMatch } = await supabase
323→        .from("profiles")
324→        .select("user_id, credits, email_enabled, inbox_email")
325→        .eq("inbox_email", recipient)
326→        .limit(1)
327→        .single();
328→
329→      if (exactMatch) {
330→        profile = exactMatch;
331→      } else if (baseRecipient !== recipient) {
332→        const { data: baseMatch } = await supabase
333→          .from("profiles")
334→          .select("user_id, credits, email_enabled, inbox_email")
335→          .eq("inbox_email", baseRecipient)
336→          .limit(1)
337→          .single();
338→        profile = baseMatch;
339→      }
340→
341→      if (!profile) {
342→        return await logAndRespond(404, { sender, recipient, status: "rejected", error_message: "Unknown inbox email" }, { error: "Unknown inbox email" });
343→      }
344→
345→      userId = profile.user_id;
346→
347→      // Check per-user email toggle
348→      if (!profile.email_enabled) {
349→        return await logAndRespond(403, { sender, recipient, user_id: userId, status: "rejected", error_message: "User email disabled" }, { error: "Email ingestion disabled for this user" });
350→      }
351→
352→      // [H3 FIX] Check that user has credits before accepting resumes
353→      if (profile.credits <= 0) {
354→        return await logAndRespond(403, { sender, recipient, user_id: userId, status: "rejected", error_message: "Insufficient credits" }, { error: "Insufficient credits" });
355→      }
356→    } else {
357→      // Verify the job owner has email enabled and has credits
358→      const { data: profile } = await supabase
359→        .from("profiles")
360→        .select("email_enabled, credits")
361→        .eq("user_id", userId)
362→        .single();
363→
364→      if (profile && !profile.email_enabled) {
365→        return await logAndRespond(403, { sender, recipient, user_id: userId, job_id: jobId, status: "rejected", error_message: "User email disabled" }, { error: "Email ingestion disabled for this user" });
366→      }
367→
368→      // [H3 FIX] Check credits for job-routed emails too
369→      if (profile && profile.credits <= 0) {
370→        return await logAndRespond(403, { sender, recipient, user_id: userId, job_id: jobId, status: "rejected", error_message: "Insufficient credits" }, { error: "Insufficient credits" });
371→      }
372→    }
373→
374→    if (attachmentFiles.length === 0) {
375→      return await logAndRespond(400, { sender, recipient, user_id: userId, job_id: jobId, status: "error", error_message: "No valid attachments (only .pdf and .docx accepted)" }, { error: "No valid attachments" });
376→    }
377→
378→    // Find or create job if not already matched by per-job routing
379→    if (!jobId) {
380→      const { data: activeJob } = await supabase
381→        .from("jobs")
382→        .select("id")
383→        .eq("user_id", userId)
384→        .eq("status", "pending")
385→        .order("created_at", { ascending: false })
386→        .limit(1)
387→        .single();
388→
389→      if (activeJob) {
390→        jobId = activeJob.id;
391→      } else {
392→        // [M4 FIX] Rate-limit auto-created jobs: max 5 auto-created jobs per user per day
393→        const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
394→        const { count: recentAutoJobs } = await supabase
395→          .from("jobs")
396→          .select("id", { count: "exact", head: true })
397→          .eq("user_id", userId)
398→          .eq("job_description", "Auto-created from email ingestion")
399→          .gte("created_at", oneDayAgo);
400→
401→        if ((recentAutoJobs || 0) >= 5) {
402→          return await logAndRespond(429, { sender, recipient, user_id: userId, status: "rejected", error_message: "Too many auto-created jobs" }, { error: "Rate limit exceeded" });
403→        }
404→
405→        const { data: newJob } = await supabase
406→          .from("jobs")
407→          .insert({
408→            user_id: userId,
409→            job_description: "Auto-created from email ingestion",
410→            status: "pending",
411→          })
412→          .select("id")
413→          .single();
414→        if (!newJob) throw new Error("Failed to create job");
415→        jobId = newJob.id;
416→      }
417→    }
418→
419→    // [H3 FIX] Check existing resume count for the job before uploading
420→    const { count: existingResumeCount } = await supabase
421→      .from("resumes")
422→      .select("id", { count: "exact", head: true })
423→      .eq("job_id", jobId);
424→
425→    const remainingSlots = maxResumesPerJob - (existingResumeCount || 0);
426→    if (remainingSlots <= 0) {
427→      return await logAndRespond(429, { sender, recipient, user_id: userId, job_id: jobId, status: "rejected", error_message: "Job has reached maximum resume limit" }, { error: "Resume limit reached for this job" });
428→    }
429→
430→    // Process attachments (limited to remaining slots)
431→    const resumeIds: string[] = [];
432→    const filesToProcess = attachmentFiles.slice(0, remainingSlots);
433→
434→    for (const att of filesToProcess) {
435→      // [M4 FIX] Sanitize filename to prevent path traversal or injection
436→      const safeName = sanitizeFilename(att.filename);
437→      const filePath = `${userId}/${jobId}/${Date.now()}_${safeName}`;
438→      await supabase.storage.from("resumes").upload(filePath, att.content);
439→
440→      const { data: resume } = await supabase
441→        .from("resumes")
442→        .insert({
443→          job_id: jobId,
444→          filename: safeName,
445→          file_path: filePath,
446→          source: "email",
447→        })
448→        .select("id")
449→        .single();
450→
451→      if (resume) resumeIds.push(resume.id);
452→    }
453→
454→    // Send confirmation email to the user (fire-and-forget)
455→    try {
456→      const { data: authUser } = await supabase.auth.admin.getUserById(userId!);
457→      const userEmail = authUser?.user?.email;
458→
459→      if (userEmail) {
460→        const { data: jobData } = await supabase.from("jobs").select("title, job_description").eq("id", jobId).single();
461→        const jobTitle = jobData?.title || jobData?.job_description?.slice(0, 50) || "Untitled Job";
462→
463→        await supabase.functions.invoke("send-email", {
464→          body: {
465→            to: userEmail,
466→            template_key: "resume_received",
467→            variables: {
468→              user_name: userEmail.split("@")[0],
469→              job_title: jobTitle,
470→              attachment_count: String(filesToProcess.length),
471→              filename: filesToProcess.map((a) => a.filename).join(", "),
472→              job_id: jobId || "",
473→              app_url: Deno.env.get("APP_URL") || "https://rankora.co",
474→            },
475→          },
476→        });
477→      }
478→    } catch (emailErr) {
479→      console.error("Failed to send resume received notification:", emailErr);
480→      await logSystemError({
481→        function_name: "email-ingest",
482→        error_type: "NOTIFICATION_SEND_ERROR",
483→        severity: "warning",
484→        error_message: errorToMessage(emailErr),
485→        error_stack: errorToStack(emailErr),
486→        user_id: userId,
487→        job_id: jobId,
488→      });
489→    }
490→
491→    return await logAndRespond(
492→      200,
493→      { sender, recipient, user_id: userId, job_id: jobId, status: "success", attachments_count: filesToProcess.length, resumes_created: resumeIds.length },
494→      { success: true, resume_ids: resumeIds, job_id: jobId }
495→    );
496→  } catch (err: unknown) {
497→    console.error("email-ingest error:", err);
498→    await logSystemError({
499→      function_name: "email-ingest",
500→      error_type: "INGEST_ERROR",
501→      severity: "critical",
502→      error_message: errorToMessage(err),
503→      error_stack: errorToStack(err),
504→    });
505→    // [H4 FIX] Return generic error — never leak internal details
506→    return new Response(JSON.stringify({ error: "Internal server error" }), {
507→      status: 500,
508→      headers: { ...corsHeaders, "Content-Type": "application/json" },
509→    });
510→  }
